// Loads the per-post approved-comment JSON files generated by the importer.
export interface WpComment {
	id: string;
	author: string;
	authorUrl: string | null;
	date: string | null;
	content: string;
	parent: string;
	type: string; // 'comment' | 'pingback' | 'trackback'
}

const files = import.meta.glob<{ default: WpComment[] }>('../data/comments/*.json', { eager: true });
const byPostId: Record<string, WpComment[]> = {};
for (const [path, mod] of Object.entries(files)) {
	const id = path.split('/').pop()!.replace('.json', '');
	byPostId[id] = mod.default;
}

export function getComments(postId?: string): WpComment[] {
	if (!postId) return [];
	return byPostId[postId] ?? [];
}
